	@Test
	void completedStoredTermSupportPrefiltersWithActualAliasesAndRetainsFilter(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc")
				.setSketchEstimatorEnabled(true)
				.setOptimizerSamplingEnabled(false);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		Literal queryEight = VF.createLiteral("08:00:00", XSD.TIME);
		Literal queryNine = VF.createLiteral("09:00:00", XSD.TIME);
		Literal storedEight = VF.createLiteral("08:00:00.000", XSD.TIME);
		Literal storedNine = VF.createLiteral("09:00:00.000", XSD.TIME);

		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.add(VF.createIRI("urn:test:train:service:0"), SCHEDULED_TIME, storedEight);
				connection.add(VF.createIRI("urn:test:train:service:1"), SCHEDULED_TIME, storedEight);
				connection.add(VF.createIRI("urn:test:train:service:2"), SCHEDULED_TIME, storedNine);
				connection.add(VF.createIRI("urn:test:train:service:3"), SCHEDULED_TIME,
						VF.createLiteral("10:00:00", XSD.TIME));
				connection.commit();
			}

			StatementPattern scheduled = new StatementPattern(Var.of("service"),
					Var.of("scheduledTimePredicate", SCHEDULED_TIME), Var.of("time"));
			ListMemberOperator selectedTimes = new ListMemberOperator();
			selectedTimes.addArgument(Var.of("time"));
			selectedTimes.addArgument(new ValueConstant(queryEight));
			selectedTimes.addArgument(new ValueConstant(queryNine));
			QueryRoot root = new QueryRoot(new Filter(scheduled, selectedTimes));

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			new LmdbFilterSimplifierOptimizer(statistics).optimize(root, null, null);

			Filter retainedFilter = assertInstanceOf(Filter.class, root.getArg(),
					"The original value-equality filter is the semantic guard");
			Join prefiltered = assertInstanceOf(Join.class, retainedFilter.getArg());
			BindingSetAssignment actualTermAnchor = assertInstanceOf(BindingSetAssignment.class,
					prefiltered.getLeftArg());
			assertInstanceOf(StatementPattern.class, prefiltered.getRightArg());

			Set<Value> anchoredValues = new LinkedHashSet<>();
			actualTermAnchor.getBindingSets()
					.forEach(bindingSet -> anchoredValues.add(bindingSet.getValue("time")));
			assertEquals(Set.of(storedEight, storedNine), anchoredValues,
					"Actual LMDB terms are deduplicated independently of their statement frequencies");
			assertFalse(anchoredValues.contains(queryEight));
			assertFalse(anchoredValues.contains(queryNine));

			ListMemberOperator retainedCondition = assertInstanceOf(ListMemberOperator.class,
					retainedFilter.getCondition());
			assertEquals(queryEight,
					assertInstanceOf(ValueConstant.class, retainedCondition.getArguments().get(1)).getValue());
			assertEquals(queryNine,
					assertInstanceOf(ValueConstant.class, retainedCondition.getArguments().get(2)).getValue());
			assertTrue(actualTermAnchor.getStringMetricPlanned("optimizer.rewriteProof")
					.contains("exactStoredTermSupport"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void temporalAliasMultiplicityNeverTriggersStatementEnumerationOrRestrictsExecution(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc")
				.setSketchEstimatorEnabled(true)
				.setOptimizerSamplingEnabled(false);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		Literal queryEight = VF.createLiteral("08:00:00", XSD.TIME);
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				for (int nanos = 1; nanos <= 4_097; nanos++) {
					connection.add(VF.createIRI("urn:test:train:service:" + nanos), SCHEDULED_TIME,
							VF.createLiteral("08:00:00." + String.format("%09d", nanos), XSD.TIME));
				}
				connection.commit();
			}
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);

			StatementPattern scheduled = new StatementPattern(Var.of("service"),
					Var.of("scheduledTimePredicate", SCHEDULED_TIME), Var.of("time"));
			ListMemberOperator selectedTimes = new ListMemberOperator();
			selectedTimes.addArgument(Var.of("time"));
			selectedTimes.addArgument(new ValueConstant(queryEight));
			QueryRoot root = new QueryRoot(new Filter(scheduled, selectedTimes));

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			StatisticsEstimate input = statistics.statementPattern(scheduled, Set.of()).orElseThrow();
			StatisticsEstimate filtered = statistics.filter(scheduled, selectedTimes, input, Set.of()).orElseThrow();
			assertEquals("frontier-v2-finite-filter-semantic-uncertain", filtered.bag().source());
			assertEquals(0.0d, filtered.metrics().get("optimizer.filterComplete"), 0.0d);

			new LmdbFilterSimplifierOptimizer(statistics).optimize(root, null, null);
			Filter retainedFilter = assertInstanceOf(Filter.class, root.getArg());
			assertInstanceOf(StatementPattern.class, retainedFilter.getArg(),
					"An incomplete term enumeration may not restrict execution");
		} finally {
			repository.shutDown();
		}
	}
